@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Nunito:wght@400;500;600;700;800;900&display=swap');
:root{--ink:#463b4a;--muted:#9c8c9d;--pink:#eb9eb4;--rose:#d87998;--cream:#fffaf7;--line:#f0e5e8;--green:#9dc8a8;--yellow:#f3c779}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#f8f2f2;color:var(--ink);font-family:'DM Sans',sans-serif;display:grid;place-items:center;padding:22px;user-select:none}.game-shell{width:min(1160px,100%);background:var(--cream);border:1px solid #f0e5e7;border-radius:22px;box-shadow:0 24px 80px #71506518;overflow:hidden}.topbar{height:74px;padding:0 28px;display:flex;align-items:center;border-bottom:1px solid var(--line);gap:24px}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-family:Nunito,sans-serif;font-size:19px;font-weight:800;line-height:1}.brand b{color:#d9809d}.brand small{display:block;font:700 8px 'DM Sans';letter-spacing:1.75px;color:#b5a5b1;margin-top:5px}.brand-mark{font-size:29px;color:#e999b1}.day-pill{margin:auto;display:flex;align-items:center;gap:10px;background:#fff6e9;border:1px solid #f8ead9;border-radius:12px;padding:8px 17px}.sun-icon{font-size:21px;color:#e6ab55}.day-pill b,.day-pill small{display:block}.day-pill b{font-size:10px;letter-spacing:1.2px}.day-pill small{font-size:10px;color:#a9948a;margin-top:2px}.top-actions{display:flex;gap:9px}.icon-btn,.edit-btn{width:34px;height:34px;border:1px solid var(--line);background:#fff;border-radius:10px;color:#927f91;font-weight:700;cursor:pointer}.icon-btn:hover,.edit-btn:hover{color:#d87998;border-color:#efc5d1}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:20px;padding:20px}.scene-wrap{height:560px;min-width:0;position:relative;overflow:hidden;border-radius:16px;background:#b9d9c1;box-shadow:inset 0 0 0 1px #ffffff77}canvas{width:100%;height:100%;display:block}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#172e3b2b,transparent 19%,transparent 77%,#372c3a42)}.scene-topline{position:absolute;left:16px;right:16px;top:15px;display:flex;justify-content:space-between;pointer-events:none}.location-chip,.weather-chip{background:#fffdf3eF;border:1px solid #fff;border-radius:9px;padding:8px 11px;font-size:9px;letter-spacing:1px;box-shadow:0 3px 12px #43433c18}.location-chip span{color:#d984a0;font-size:13px;margin-right:5px}.weather-chip{display:flex;gap:6px;align-items:center;color:#807b70}.weather-chip span:first-child{color:#eab45f;font-size:14px}.scene-caption{position:absolute;bottom:15px;left:16px;color:#fff;font-size:11px;text-shadow:0 1px 5px #3338;letter-spacing:.1px}.caption-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#ffcf83;margin:0 6px 1px 0}.interact-btn{position:absolute;bottom:14px;right:15px;border:1px solid #ffffffa8;background:#fffcf2;color:#8f6576;padding:8px 12px;border-radius:9px;font:700 10px 'DM Sans';cursor:pointer;box-shadow:0 4px 12px #4e42551c}.interact-btn span{color:#d88ca5;margin-right:5px}.interact-btn kbd{font:600 8px 'DM Sans';color:#ad9c9e;border-left:1px solid #eadfe1;padding-left:7px;margin-left:6px}.interact-btn:hover{transform:translateY(-1px);background:#fff}.sidebar{display:flex;flex-direction:column;gap:12px}.profile-card,.needs-card,.quest-card,.bag-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px 15px}.profile-head{display:flex;align-items:center;gap:11px;position:relative}.avatar{width:48px;height:48px;border-radius:50%;background:linear-gradient(135deg,#fbd7df,#f9ebce);display:grid;place-items:center;color:#da849d;font-size:19px;border:2px solid #fff;box-shadow:0 0 0 1px #f0d7dc;position:relative;overflow:hidden}.avatar:before{content:' ';position:absolute;width:24px;height:25px;border-radius:48% 48% 42% 42%;background:#fff0df;top:13px;box-shadow:0 -8px 0 4px #654c5b}.avatar:after{content:'•  •';position:absolute;top:24px;font-size:8px;letter-spacing:4px;color:#584853}.avatar span{position:absolute;right:2px;top:0;z-index:1;font-size:10px}.eyebrow{font-size:8px;letter-spacing:1.3px;color:#b39aa8;font-weight:700}.profile-head h1{font:800 21px Nunito;margin:2px 0 0;color:#514352}.profile-head p{font-size:10px;color:#a4919d;margin:1px 0}.profile-head p span{color:#e8a3b8}.edit-btn{margin-left:auto;width:27px;height:27px;border:0;background:#fff7f8}.level-row{display:flex;justify-content:space-between;margin:13px 0 6px;color:#a693a0;font-size:8px;letter-spacing:.7px;font-weight:700}.level-row b{color:#d57c97;margin-left:3px}.level-row span:last-child{letter-spacing:0;font-size:9px}.xp-track,.need-track{height:6px;border-radius:10px;background:#f4edf0;overflow:hidden}.xp-track i,.need-track i{height:100%;display:block;width:20%;border-radius:inherit;background:linear-gradient(90deg,#e99bb1,#f2b1be);transition:width .4s}.section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.section-title h2{font:800 12px Nunito;margin:0;color:#584a59}.mood{font-size:9px;color:#cd8299;background:#fff3f5;border-radius:8px;padding:5px 7px}.need{margin:9px 0}.need-label{font-size:9px;color:#887986;display:flex;align-items:center;gap:6px;margin-bottom:5px}.need-label span{color:#d98ca3;font-size:12px}.need-label b{margin-left:auto;color:#736477;font-size:9px}.need-track{height:5px}.need-track.pink i{background:linear-gradient(90deg,#e98eaa,#f2b6c4)}.need-track.yellow i{background:linear-gradient(90deg,#e9ba62,#f4d28d)}.need-track.green i{background:linear-gradient(90deg,#8fc39b,#badbb6)}.quest-count{font-size:9px;color:#ca8799;background:#fff3f5;padding:4px 7px;border-radius:8px}.quest-list{display:flex;flex-direction:column;gap:8px}.quest{display:flex;align-items:center;gap:8px;font-size:9px;color:#8a7a89;line-height:1.3}.quest-check{width:15px;height:15px;border:1px solid #eadce2;border-radius:5px;flex:none;display:grid;place-items:center;color:#fff;font-size:9px}.quest.done .quest-check{background:#a9cdb0;border-color:#a9cdb0}.quest.done span:last-child{text-decoration:line-through;color:#bcaeb8}.bag-card{padding-bottom:12px}.bag-card .section-title{margin-bottom:9px}.tiny-link{border:0;background:none;color:#b9a7b3;cursor:pointer}.inventory{display:flex;gap:8px}.item,.shop-button{height:37px;min-width:48px;border:1px solid #f1e7e9;background:#fff9f9;border-radius:9px;display:flex;align-items:center;justify-content:center;gap:5px;color:#887486;font-size:10px}.item span{font-size:15px}.item b{font-size:9px}.shop-button{margin-left:auto;min-width:37px;background:#fdf1f4;border-color:#f5e1e6;color:#ce8097;font-size:17px;cursor:pointer}.tip{display:flex;align-items:flex-start;gap:9px;padding:4px 8px;color:#a5919c;font-size:9px;line-height:1.5}.tip>span:first-child{font-size:15px;color:#e8b66d}.tip b{color:#8e7788;font-size:9px}.bottom-bar{height:47px;border-top:1px solid var(--line);display:flex;align-items:center;padding:0 25px;color:#a08e9b;font-size:9px}.controls-hint{display:flex;align-items:center;gap:4px}.keycap{background:#fff;border:1px solid #eadfe4;border-bottom-width:2px;border-radius:4px;padding:2px 5px;color:#977f8e;font-size:8px;font-weight:700}.keycap.wide{padding:2px 7px}.controls-hint>span:last-child{margin-left:2px}.hint-divider{padding:0 7px;color:#ddc8d1}.footer-note{margin:auto;font-style:italic}.footer-note span{color:#e5a0b2}.map-btn{border:0;background:none;color:#c57f96;font-size:12px;cursor:pointer}.map-btn span{font-size:8px;font-weight:700;letter-spacing:1px;margin-left:3px}.modal-backdrop{position:fixed;inset:0;background:#3c30454d;display:grid;place-items:center;padding:20px;z-index:5;backdrop-filter:blur(3px)}.modal-backdrop[hidden]{display:none}.modal{position:relative;width:min(380px,100%);border-radius:20px;background:#fffaf7;padding:28px 30px 25px;text-align:center;box-shadow:0 20px 70px #38283944;border:1px solid #fff}.modal-close{position:absolute;right:15px;top:12px;border:0;background:transparent;color:#b5a0ab;font-size:22px;cursor:pointer}.modal-icon{font-size:35px;color:#e69ab0;margin-bottom:6px}.modal h2{font:800 23px Nunito;margin:6px 0;color:#524451}.modal p{font-size:12px;line-height:1.7;color:#8e7c89;margin:9px 0 18px}.modal-choices{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}.choice-btn{border:1px solid #f0dce2;background:#fff2f5;color:#ba718b;border-radius:9px;padding:9px 13px;font:700 10px 'DM Sans';cursor:pointer}.choice-btn:hover{background:#f8dfe6}.choice-btn.secondary{background:#fff;color:#9e8b98;border-color:#eee3e7}.toast{position:absolute;left:50%;top:58px;transform:translate(-50%,-10px);background:#fffdf3;border:1px solid #fff;border-radius:10px;padding:9px 14px;font-size:11px;color:#896d7d;box-shadow:0 6px 20px #51445430;opacity:0;pointer-events:none;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-pad{display:none}
@media(max-width:850px){body{padding:0;background:var(--cream);display:block}.game-shell{border:0;border-radius:0;min-height:100vh;box-shadow:none}.topbar{height:62px;padding:0 16px}.game-layout{display:flex;flex-direction:column;padding:12px;gap:12px}.scene-wrap{height:min(56vh,490px);min-height:320px;flex:none}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:9px}.profile-card,.needs-card,.quest-card,.bag-card{padding:12px}.tip{display:none}.bottom-bar{padding:0 14px;height:42px}.footer-note{display:none}.controls-hint{margin:auto}.map-btn{position:absolute;right:15px}.profile-head h1{font-size:18px}.avatar{width:41px;height:41px}.scene-caption{bottom:14px;max-width:60%;line-height:1.4}.interact-btn{bottom:12px}.day-pill{padding:7px 10px}.brand{font-size:17px}.top-actions{gap:5px}.icon-btn{width:30px;height:30px}}
@media(max-width:500px){.topbar{gap:8px}.day-pill{margin-left:auto;margin-right:auto}.game-layout{padding:9px}.scene-wrap{height:50vh;min-height:285px}.sidebar{grid-template-columns:1fr 1fr}.profile-card,.needs-card{min-height:133px}.quest-card,.bag-card{min-height:115px}.quest-list{gap:6px}.quest{font-size:8px}.inventory{gap:4px}.item{min-width:39px}.shop-button{min-width:31px}.bottom-bar{position:relative}.mobile-pad{display:flex;position:absolute;bottom:54px;left:12px;flex-direction:column;gap:3px}.mobile-pad div{display:flex;gap:3px}.mobile-pad button{width:34px;height:32px;background:#fffdf2dc;border:1px solid #ffffff;border-radius:8px;color:#967688;font-size:12px;box-shadow:0 2px 7px #51445427;touch-action:none}.interact-btn{padding:8px 9px}.interact-btn kbd{display:none}.scene-caption{max-width:58%;font-size:9px}.location-chip,.weather-chip{padding:7px 8px;font-size:8px}}

(() => {
  const canvas = document.querySelector('#world'), ctx = canvas.getContext('2d');
  const ui = Object.fromEntries(['dayLabel','timeLabel','locationName','weatherIcon','weatherName','sceneCaption','toast','playerName','level','xpText','xpBar','happyVal','happyBar','energyVal','energyBar','friendVal','friendBar','mood','questCount','questList','berryCount','flowerCount','coinCount','modalBackdrop','modalIcon','modalEyebrow','modalTitle','modalText','modalChoices'].map(id=>[id,document.getElementById(id)]));
  const state={x:480,y:378,dir:0,walk:0,day:1,minutes:480,xp:20,level:1,happy:78,energy:85,friend:32,berries:2,flowers:0,coins:12,quests:{walk:false,talk:false,flower:false},name:localStorage.getItem('hanamiName')||'Mika',near:null,modal:false};
  const questDefs=[['walk','Take a stroll around town'],['talk','Say hello to someone new'],['flower','Pick a little flower']];
  const stations=[{id:'cafe',x:145,y:290,r:82,name:'MAPLE CAFÉ',kind:'cafe'},{id:'npc',x:616,y:348,r:68,name:'YUI',kind:'npc'},{id:'flower',x:800,y:397,r:70,name:'FLOWER PATCH',kind:'flower'},{id:'bench',x:340,y:365,r:68,name:'THE OLD BENCH',kind:'bench'},{id:'shop',x:145,y:290,r:90,name:'MAPLE CAFÉ',kind:'cafe'}];
  const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
  function updateUI(){
    document.querySelector('#playerName').textContent=state.name;
    document.querySelector('#level').textContent=String(state.level).padStart(2,'0');
    ui.xpText.textContent=`${state.xp} / 100 XP`;ui.xpBar.style.width=`${state.xp}%`;
    for(const [key,val] of [['happy',state.happy],['energy',state.energy],['friend',state.friend]]){document.querySelector(`#${key}Val`).textContent=val;document.querySelector(`#${key}Bar`).style.width=val+'%';}
    ui.berryCount.textContent=state.berries;ui.flowerCount.textContent=state.flowers;ui.coinCount.textContent=state.coins;
    ui.questList.innerHTML=questDefs.map(([id,text])=>`<div class="quest ${state.quests[id]?'done':''}"><span class="quest-check">${state.quests[id]?'✓':''}</span><span>${text}</span></div>`).join('');
    const done=Object.values(state.quests).filter(Boolean).length;ui.questCount.textContent=`${done} / 3`;
    ui.dayLabel.textContent=['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'][(state.day-1)%7];
    const h=Math.floor(state.minutes/60)%12||12,m=state.minutes%60;ui.timeLabel.textContent=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')} ${state.minutes<720?'AM':'PM'}`;
    ui.mood.textContent=state.happy>65?'✧ cozy':state.happy>35?'♡ okay':'☁ a little low';
  }
  function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/960,0,0,canvas.height/560,0,0)}
  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
  function path(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(...points[0]);for(let i=1;i<points.length;i++)ctx.lineTo(...points[i]);ctx.closePath();ctx.fill()}
  function drawWorld(t){
    // warm sky and far hills
    let g=ctx.createLinearGradient(0,0,0,560);g.addColorStop(0,'#a9d8d1');g.addColorStop(.58,'#d7e8c9');g.addColorStop(1,'#e5e3bd');ctx.fillStyle=g;ctx.fillRect(0,0,960,560);
    ellipse(812,87,37,37,'#ffe9a8');ellipse(812,87,51,51,'#ffe9a833');
    path([[0,237],[85,182],[170,228],[276,164],[380,227],[495,169],[614,235],[738,173],[845,226],[960,176],[960,334],[0,334]],'#a7cbaa');
    path([[0,273],[110,213],[231,279],[356,206],[480,274],[604,208],[745,281],[860,212],[960,260],[960,360],[0,360]],'#8fbb96');
    // distant town
    for(let i=0;i<7;i++){const x=i*157-16,w=105+(i%3)*16,y=228+(i%2)*18;rounded(x,y,w,122,5,['#f2cdbd','#f7e2bb','#e9c4ca','#f3d9bd'][i%4]);ctx.fillStyle='#bd958c';ctx.fillRect(x-4,y-8,w+8,12);for(let wx=x+14;wx<x+w-10;wx+=31){rounded(wx,y+29,15,20,3,'#9cc8c2');rounded(wx,y+62,15,19,3,'#9cc8c2');}}
    // blossom branches
    for(const side of [0,1]){let bx=side?918:45,by=158;ctx.strokeStyle='#735c50';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(bx,by+105);ctx.quadraticCurveTo(bx+(side?-27:30),by+26,bx+(side?-69:65),by-29);ctx.stroke();for(let i=0;i<17;i++){let x=bx+(side?-1:1)*(12+(i*19)%72),y=by+20-(i*17)%90;blossom(x,y,4.5);}}
    // street depth
    path([[0,324],[960,324],[960,560],[0,560]],'#e9dcbf');path([[0,389],[960,389],[960,560],[0,560]],'#d9c9ad');
    // sidewalk slabs and road
    path([[0,418],[960,418],[960,560],[0,560]],'#aeb8a0');
    ctx.strokeStyle='#c9d0b6';ctx.lineWidth=3;for(let x=0;x<960;x+=112){ctx.beginPath();ctx.moveTo(x,390);ctx.lineTo(x-25,418);ctx.stroke();}
    // road markings
    ctx.fillStyle='#f2e8c7';for(let x=38;x<960;x+=180)ctx.fillRect(x,490,68,5);
    // cafe foreground, left
    rounded(30,257,190,154,8,'#dc9c8b');rounded(40,267,170,134,6,'#f3d7b8');path([[24,273],[124,220],[225,273]],'#bb817d');path([[36,269],[124,230],[212,269]],'#f6c6b8');
    rounded(75,304,58,50,5,'#9cc9c1');ctx.strokeStyle='#fff4d9';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(104,304);ctx.lineTo(104,354);ctx.moveTo(75,329);ctx.lineTo(133,329);ctx.stroke();rounded(148,305,44,96,4,'#a77669');rounded(158,317,23,34,3,'#b7d8cb');
    // awning
    for(let i=0;i<6;i++){rounded(44+i*28,274,28,21,3,i%2?'#fff1d2':'#df8690');}rounded(80,244,90,25,5,'#fff6e2');ctx.fillStyle='#9b6f73';ctx.font='bold 11px Nunito';ctx.textAlign='center';ctx.fillText('MAPLE CAFÉ',125,261);
    // garden and fence right
    for(let i=0;i<8;i++){let x=711+i*31;rounded(x,353,7,67,2,'#b99176');}ctx.fillStyle='#b99176';ctx.fillRect(702,367,260,5);ctx.fillRect(702,400,260,5);
    for(let i=0;i<14;i++){let x=725+(i*47)%231,y=370+(i*29)%65;blossom(x,y,7+(i%3));ctx.strokeStyle='#6d9d6d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y+5);ctx.lineTo(x,y+24);ctx.stroke();}
    // bench
    rounded(299,362,99,10,3,'#a97764');rounded(303,374,91,9,3,'#b98670');ctx.fillStyle='#806557';ctx.fillRect(312,383,5,21);ctx.fillRect(379,383,5,21);rounded(293,349,108,9,4,'#bb8d71');
    // little flower stand sign
    rounded(733,293,145,35,8,'#fff8e9');ctx.fillStyle='#806b73';ctx.font='bold 10px Nunito';ctx.fillText('MIMI’S FLOWERS',805,315);
    // floating foliage
    for(let i=0;i<6;i++){ellipse((i*179+43)%960,448+(i%3)*32,13,4,'#91b28a');}
    drawNpc(616,343,t);drawPlayer(t);
    // sparkling petals
    for(let i=0;i<11;i++){let x=(i*127+Math.sin(t/800+i)*14)%960,y=(i*71+t/80)%310;ctx.globalAlpha=.5;blossom(x,y,2.4);ctx.globalAlpha=1;}
  }
  function blossom(x,y,r){for(let i=0;i<5;i++){let a=i*Math.PI*2/5;ellipse(x+Math.cos(a)*r*.85,y+Math.sin(a)*r*.85,r*.57,r*.43,'#f5c5d0');}ellipse(x,y,r*.28,r*.28,'#f5dc9c')}
  function drawNpc(x,y,t){let bob=Math.sin(t/350)*2;ellipse(x,y+24,14,5,'#556b5560');ctx.save();ctx.translate(x,y+bob); // sweet Yui
    rounded(-10,1,20,24,7,'#8eb6b0');path([[-10,9],[-19,27],[0,23],[18,27],[10,9]],'#8eb6b0');ellipse(0,-8,13,15,'#f6d2b7');ellipse(0,-15,14,12,'#694d5e');ellipse(-11,-5,4,10,'#694d5e');ellipse(11,-5,4,10,'#694d5e');ellipse(-4,-7,1.3,1.8,'#473c4b');ellipse(4,-7,1.3,1.8,'#473c4b');ctx.strokeStyle='#be7482';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,-2,2,0.2,2.7);ctx.stroke();ctx.restore();}
  function drawPlayer(t){const walking=keys.size>0,bob=walking?Math.sin(state.walk)*3:Math.sin(t/480)*1.5;ellipse(state.x,state.y+25,16,6,'#665d4f55');ctx.save();ctx.translate(state.x,state.y+bob);if(state.dir===1)ctx.scale(-1,1);
    // legs and shoes
    rounded(-9,12,7,16,4,'#fff0dd');rounded(2,12,7,16,4,'#fff0dd');ellipse(-6,28,6,3,'#d48799');ellipse(7,28,6,3,'#d48799');
    // dress
    path([[-9,-1],[9,-1],[15,20],[-15,20]],'#e994aa');rounded(-9,-7,18,17,6,'#f4afbd');ctx.fillStyle='#ffe9db';ctx.beginPath();ctx.moveTo(-5,-5);ctx.lineTo(0,1);ctx.lineTo(5,-5);ctx.fill();
    // arms
    rounded(-15,0,6,17,3,'#f3cdb3');rounded(9,0,6,17,3,'#f3cdb3');
    // hair/head
    ellipse(0,-15,14,16,'#f2cfb3');ellipse(0,-22,15,12,'#594454');ellipse(-11,-17,4,10,'#594454');ellipse(11,-17,4,10,'#594454');path([[-14,-21],[-9,-34],[2,-35],[14,-26],[7,-24],[1,-28],[-4,-23],[-9,-26]],'#594454');
    ellipse(-5,-16,1.6,2.2,'#4e424f');ellipse(5,-16,1.6,2.2,'#4e424f');ellipse(-8,-11,2,1,'#e89aa2');ellipse(8,-11,2,1,'#e89aa2');ctx.strokeStyle='#b86e7c';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,-11,2.7,.3,2.8);ctx.stroke();
    // bow
